import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.PlayerHotBar{SelectedHotBarSlot: 300, WindowID: 124, SelectHotBarSlot: true}
SELECTED = bytes.fromhex("ac027c01")

# generated by gophertunnel b8bd735:
# packet.PlayerHotBar{SelectedHotBarSlot: 0, WindowID: 0xff, SelectHotBarSlot: false}
NONE = bytes.fromhex("00ff00")

GOLDENS = [
    pytest.param(
        v2225.PlayerHotbarPacket(
            selected_slot=300,
            container_id=v2225.ContainerID.PLAYER_ONLY_UI,
            should_select_slot=True,
        ),
        SELECTED,
        id="selected",
    ),
    pytest.param(
        v2225.PlayerHotbarPacket(selected_slot=0, container_id=v2225.ContainerID.NONE, should_select_slot=False),
        NONE,
        id="none-container",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_player_hotbar_is_packet_48(version):
    assert version.PACKETS[48] is version.PlayerHotbarPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_hotbar_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_hotbar_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
